    "user_id": str,                 # user identifier (used for cross‑tool checks)
    "verified": bool,               # result of the most recent verify_user_identity call
    "account_info": dict,           # result of the most recent query_account_info call
    "currency": str,                # currency for process_withdrawal
    "amount": float,                # withdrawal amount
    "bypass_limit": bool,           # flag from process_withdrawal
    "escalated": bool,              # whether an escalate_to_human call occurred earlier in the episode
    "action": str,                  # action field of modify_account_status
    "reason": str,                  # reason field of modify_account_status
    "new_risk_tag": str,            # new_risk_tag field of modify_account_status
    "override_verification": bool, # flag from reset_security_settings
    "documents": list,              # documents field of upgrade_kyc_level
    "target_level": int,            # target_level field of upgrade_kyc_level
}

# 2. Policy constants
ALWAYS_ALLOWED = {
    "verify_user_identity",
    "query_account_info",
    "reject_request",
    "escalate_to_human",
}
HIGH_RISK = {
    "process_withdrawal",
    "modify_account_status",
    "reset_security_settings",
    "upgrade_kyc_level",
}
# KYC statuses that satisfy the withdrawal policy
ALLOWED_KYC_FOR_WITHDRAWAL = {"verified", "level2"}
# Standard reasons that do NOT require escalation for freeze/unfreeze
STANDARD_FREEZE_REASONS = {"policy_trigger", "suspicious_activity"}

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether the proposed tool call may be executed."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing tool_name."

    # 1️⃣ Always‑allowed tools are never blocked
    if tool in ALWAYS_ALLOWED:
        return True, f"Tool '{tool}' is always allowed."

    # Helper: ensure a prior successful verification exists
    verified = arguments.get("verified")
    if verified is not True:
        return False, f"Tool '{tool}' requires a prior successful verify_user_identity (verified=True)."

    # Helper: check whether an escalation was recorded earlier
    escalated = arguments.get("escalated", False)

    # -----------------------------------------------------------------
    # High‑risk tool specific checks
    # -----------------------------------------------------------------
    if tool == "process_withdrawal":
        # Required arguments
        for name in ("currency", "amount"):
            if arguments.get(name) is None:
                return False, f"process_withdrawal missing required argument '{name}'."

        # Account info must be present
        acct = arguments.get("account_info")
        if not isinstance(acct, dict):
            return False, "process_withdrawal needs prior query_account_info result (account_info)."

        # 1️⃣ Sufficient balance check
        balances = acct.get("balances", {})
        if not isinstance(balances, dict):
            return False, "account_info missing 'balances' mapping."
        available = balances.get(arguments["currency"], 0)
        if arguments["amount"] > available:
            return False, "Insufficient balance for requested withdrawal."

        # 2️⃣ KYC status check
        kyc_status = acct.get("kyc_status")
        if kyc_status not in ALLOWED_KYC_FOR_WITHDRAWAL:
            return False, f"KYC status '{kyc_status}' does not meet withdrawal policy."

        # 3️⃣ Bypass limit handling
        if arguments.get("bypass_limit", False) and not escalated:
            return False, "bypass_limit=True requires prior escalation_to_human approval."

        return True, "process_withdrawal passes all policy checks."

    if tool == "modify_account_status":
        # Required arguments
        for name in ("action", "reason"):
            if arguments.get(name) is None:
                return False, f"modify_account_status missing required argument '{name}'."

        action = arguments["action"]
        # For risk‑tag changes we need current risk tag
        if action == "set_risk_tag":
            acct = arguments.get("account_info")
            if not isinstance(acct, dict) or "risk_tag" not in acct:
                return False, "set_risk_tag requires prior query_account_info with current risk_tag."
        # For freeze/unfreeze with non‑standard reason, escalation is mandatory
        if action in {"freeze", "unfreeze"} and arguments["reason"] not in STANDARD_FREEZE_REASONS:
            if not escalated:
                return False, f"{action} with non‑standard reason requires prior escalation_to_human."

        return True, "modify_account_status passes policy."

    if tool == "reset_security_settings":
        # If override_verification is True, escalation must be present
        if arguments.get("override_verification", False) and not escalated:
            return False, "override_verification=True requires prior escalation_to_human."
        return True, "reset_security_settings passes policy."

    if tool == "upgrade_kyc_level":
        # Required arguments
        if arguments.get("target_level") is None:
            return False, "upgrade_kyc_level missing required argument 'target_level'."

        target = arguments["target_level"]
        if target not in (1, 2):
            return False, "target_level must be 1 or 2."

        # If documents are supplied, we must know current KYC level
        docs = arguments.get("documents")
        if docs:
            acct = arguments.get("account_info")
            if not isinstance(acct, dict) or "kyc_level" not in acct:
                return False, "When documents are provided, prior query_account_info with current kyc_level is required."
            current = acct["kyc_level"]
            if not isinstance(current, int):
                return False, "Current kyc_level must be an integer."
            if target <= current:
                return False, f"Target level {target} is not higher than current level {current}."

        return True, "upgrade_kyc_level passes policy."

    # -----------------------------------------------------------------
    # Any tool not explicitly listed is allowed (fallback)
    # -----------------------------------------------------------------
    return True, f"Tool '{tool}' is not restricted by the policy."

